    19	{
    20	// format info from http://www.fileformat.info/format/sunraster/egff.htm
    21	
    22	// Header format of saved files.
    23	quint32 rasMagicBigEndian = 0x59a66a95;
    24	// quint32 rasMagicLittleEndian = 0x956aa659; # used to support wrong encoded files
    25	
    26	enum RASType {
    27	    RAS_TYPE_OLD            = 0x0,
    28	    RAS_TYPE_STANDARD       = 0x1,
    29	    RAS_TYPE_BYTE_ENCODED       = 0x2,
    30	    RAS_TYPE_RGB_FORMAT     = 0x3,
    31	    RAS_TYPE_TIFF_FORMAT        = 0x4,
    32	    RAS_TYPE_IFF_FORMAT     = 0x5,
    33	    RAS_TYPE_EXPERIMENTAL       = 0xFFFF
    34	};
    35	
    36	enum RASColorMapType {
    37	    RAS_COLOR_MAP_TYPE_NONE     = 0x0,
    38	    RAS_COLOR_MAP_TYPE_RGB      = 0x1,
    39	    RAS_COLOR_MAP_TYPE_RAW      = 0x2
    40	};
    41	
    42	struct RasHeader {
    43	    quint32 MagicNumber;
    44	    quint32 Width;
    45	    quint32 Height;
    46	    quint32 Depth;
    47	    quint32 Length;
    48	    quint32 Type;
    49	    quint32 ColorMapType;
    50	    quint32 ColorMapLength;
    51	    enum { SIZE = 32 }; // 8 fields of four bytes each
    52	};
    53	
    54	static QDataStream &operator>> (QDataStream &s, RasHeader &head)
    55	{
    56	    s >> head.MagicNumber;
    57	    s >> head.Width;
    58	    s >> head.Height;
    59	    s >> head.Depth;
    60	    s >> head.Length;
    61	    s >> head.Type;
    62	    s >> head.ColorMapType;
    63	    s >> head.ColorMapLength;
    64	    /*qDebug() << "MagicNumber: " << head.MagicNumber
    65	             << "Width: " << head.Width
    66	             << "Height: " << head.Height
    67	             << "Depth: " << head.Depth
    68	             << "Length: " << head.Length
    69	             << "Type: " << head.Type
    70	             << "ColorMapType: " << head.ColorMapType
    71	             << "ColorMapLength: " << head.ColorMapLength;*/
    72	    return s;
    73	}
    74	
    75	static bool IsSupported(const RasHeader &head)
    76	{
    77	    // check magic number
    78	    if (head.MagicNumber != rasMagicBigEndian) {
    79	        return false;
    80	    }
    81	    // check for an appropriate depth
    82	    // we support 8bit+palette, 24bit and 32bit ONLY!
    83	    // TODO: add support for 1bit
    84	    if (!((head.Depth == 8 && head.ColorMapType == 1)
    85	            || head.Depth == 24 || head.Depth == 32)) {
    86	        return false;
    87	    }
    88	    // the Type field adds support for RLE(BGR), RGB and other encodings
    89	    // we support Type 1: Normal(BGR) and Type 3: Normal(RGB) ONLY!
    90	    // TODO: add support for Type 2: RLE(BGR) & Type 4,5: TIFF/IFF
    91	    if (!(head.Type == 1 || head.Type == 3)) {
    92	        return false;
    93	    }
    94	    // Old files didn't have Length set - reject them for now
    95	    // TODO: add length recalculation to support old files
    96	    if (!head.Length) {
    97	        return false;
    98	    }
    99	    return true;
   100	}
   101	
   102	static bool LoadRAS(QDataStream &s, const RasHeader &ras, QImage &img)
   103	{
   104	    s.device()->seek(RasHeader::SIZE);
   105	
   106	    // QVector uses some extra space for stuff, hence the 32 here suggested by thiago
   107	    if (ras.ColorMapLength > std::numeric_limits<int>::max() - 32) {
   108	        qWarning() << "LoadRAS() unsupported image color map length in file header" << ras.ColorMapLength;
   109	        return false;
   110	    }
   111	
   112	    // Read palette if needed.
   113	    QVector<quint8> palette(ras.ColorMapLength);
   114	    if (ras.ColorMapType == 1) {
   115	        for (quint32 i = 0; i < ras.ColorMapLength; ++i) {
   116	            s >> palette[i];
   117	        }
   118	    }
   119	
   120	    const int bpp = ras.Depth / 8;
   121	    if (ras.Height == 0) {
   122	        return false;
   123	    }
   124	    if (bpp == 0) {
   125	        return false;
   126	    }
   127	    if (ras.Length / ras.Height / bpp < ras.Width) {
   128	        qWarning() << "LoadRAS() mistmatch between height and width" << ras.Width << ras.Height << ras.Length << ras.Depth;
   129	        return false;
   130	    }
   131	    // QVector uses some extra space for stuff, hence the 32 here suggested by thiago
   132	    if (ras.Length > std::numeric_limits<int>::max() - 32) {
   133	        qWarning() << "LoadRAS() unsupported image length in file header" << ras.Length;
   134	        return false;
   135	    }
   136	
   137	    // each line must be a factor of 16 bits, so they may contain padding
   138	    // this will be 1 if padding required, 0 otherwise
   139	    const int paddingrequired = (ras.Width * bpp % 2);
   140	
   141	    // qDebug() << "paddingrequired: " << paddingrequired;
   142	    // don't trust ras.Length
   143	    QVector<quint8> input(ras.Length);
   144	
   145	    int i = 0;
   146	    while (! s.atEnd()) {
   147	        s >> input[i];
   148	        // I guess we need to find out if we're at the end of a line
   149	        if (paddingrequired && i != 0 && !(i % (ras.Width * bpp))) {
   150	            s >> input[i];
   151	        }
   152	        i++;
   153	    }
   154	
   155	    // Allocate image
   156	    img = QImage(ras.Width, ras.Height, QImage::Format_ARGB32);
   157	
   158	    if (img.isNull())
   159	        return false;
   160	
   161	    // Reconstruct image from RGB palette if we have a palette
   162	    // TODO: make generic so it works with 24bit or 32bit palettes
   163	    if (ras.ColorMapType == 1 && ras.Depth == 8) {
   164	        quint8 red, green, blue;
   165	        for (quint32 y = 0; y < ras.Height; y++) {
   166	            for (quint32 x = 0; x < ras.Width; x++) {
   167	                red = palette.value((int)input[y * ras.Width + x]);
   168	                green = palette.value((int)input[y * ras.Width + x] + (ras.ColorMapLength / 3));
   169	                blue = palette.value((int)input[y * ras.Width + x] + 2 * (ras.ColorMapLength / 3));
   170	                img.setPixel(x, y, qRgb(red, green, blue));
   171	            }
   172	        }
   173	
   174	    }
   175	
   176	    if (ras.ColorMapType == 0 && ras.Depth == 24 && (ras.Type == 1 || ras.Type == 2)) {
   177	        quint8 red, green, blue;
   178	        for (quint32 y = 0; y < ras.Height; y++) {
   179	            for (quint32 x = 0; x < ras.Width; x++) {
   180	                red = input[y * 3 * ras.Width + x * 3 + 2];
   181	                green = input[y * 3 * ras.Width + x * 3 + 1];
   182	                blue = input[y * 3 * ras.Width + x * 3];
   183	                img.setPixel(x, y, qRgb(red, green, blue));
   184	            }
   185	        }
   186	    }
   187	
   188	    if (ras.ColorMapType == 0 && ras.Depth == 24 && ras.Type == 3) {
   189	        quint8 red, green, blue;
   190	        for (quint32 y = 0; y < ras.Height; y++) {
   191	            for (quint32 x = 0; x < ras.Width; x++) {
   192	                red = input[y * 3 * ras.Width + x * 3];
   193	                green = input[y * 3 * ras.Width + x * 3 + 1];
   194	                blue = input[y * 3 * ras.Width + x * 3 + 2];
   195	                img.setPixel(x, y, qRgb(red, green, blue));
   196	            }
   197	        }
   198	    }
   199	
   200	    if (ras.ColorMapType == 0 && ras.Depth == 32 && (ras.Type == 1 || ras.Type == 2)) {
   201	        quint8 red, green, blue;
   202	        for (quint32 y = 0; y < ras.Height; y++) {
   203	            for (quint32 x = 0; x < ras.Width; x++) {
   204	                red = input[y * 4 * ras.Width + x * 4 + 3];
   205	                green = input[y * 4 * ras.Width + x * 4 + 2];
   206	                blue = input[y * 4 * ras.Width + x * 4 + 1];
   207	                img.setPixel(x, y, qRgb(red, green, blue));
   208	            }
   209	        }
   210	    }
   211	
   212	    if (ras.ColorMapType == 0 && ras.Depth == 32 && ras.Type == 3) {
   213	        quint8 red, green, blue;
   214	        for (quint32 y = 0; y < ras.Height; y++) {
   215	            for (quint32 x = 0; x < ras.Width; x++) {
   216	                red = input[y * 4 * ras.Width + x * 4 + 1];
   217	                green = input[y * 4 * ras.Width + x * 4 + 2];
   218	                blue = input[y * 4 * ras.Width + x * 4 + 3];
   219	                img.setPixel(x, y, qRgb(red, green, blue));
   220	            }
   221	        }
   222	    }
   223	
   224	    return true;
   225	}
   226	} // namespace
